mapper.select:
SELECT l.*, s.name AS store_name
FROM chain_franchise_ledger l
LEFT JOIN store_info s ON s.id = l.store_id

    l.store_id = #{storeId}
    AND l.biz_date >= #{begin}
    AND l.biz_date <= #{end}

        AND (l.transfer_no LIKE CONCAT('%', #{keyword}, '%') OR l.source_no LIKE CONCAT('%', #{keyword}, '%')
             OR l.bill_no LIKE CONCAT('%', #{keyword}, '%'))


        AND l.store_id IN #{sid}


ORDER BY l.biz_date DESC, l.id DESC
